#!/usr/bin/env python3
"""Comic Chaos - Web Interface with Interactive Panels"""

import re
import time

from flask import Flask, render_template, request, jsonify, Response

from .config import COMICS_DIR, get_openai_api_key
from .comic_registry import ComicRegistry
from .comic_session import ComicSession

app = Flask(__name__)

# Active sessions, in memory. A restarted server forgets them.
sessions = {}

# Track last-access time per session for TTL-based eviction.
session_timestamps = {}
SESSION_TTL_SECONDS = 3600  # 60 minutes

# Session IDs are generated by the browser, so only a conservative character set is accepted.
SESSION_ID_PATTERN = re.compile(r"[A-Za-z0-9_-]{16,128}")


def is_valid_session_id(session_id) -> bool:
    """Return True if a client-supplied session ID is safe to use."""
    return isinstance(session_id, str) and SESSION_ID_PATTERN.fullmatch(session_id) is not None


def json_body() -> dict:
    """Parse the request's JSON object body, tolerating missing or malformed JSON."""
    data = request.get_json(silent=True)
    return data if isinstance(data, dict) else {}


def touch_session(session_id):
    """Record that a session was just accessed."""
    session_timestamps[session_id] = time.monotonic()


def cleanup_stale_sessions():
    """Evict sessions that haven't been accessed within the TTL.

    Called at the start of new session creation to keep memory bounded.
    """
    now = time.monotonic()
    stale = [
        sid for sid, ts in session_timestamps.items()
        if now - ts > SESSION_TTL_SECONDS
    ]
    for sid in stale:
        sessions.pop(sid, None)
        session_timestamps.pop(sid, None)
    if stale:
        print(f"[SESSION] Cleaned up {len(stale)} stale session(s)")


def get_session(session_id):
    """Look up an active session."""
    session = sessions.get(session_id)
    if session:
        touch_session(session_id)
    return session


def event_stream(events) -> Response:
    """Stream JSON events to the browser as Server-Sent Events."""
    return Response(
        (f"data: {event}\n\n" for event in events),
        mimetype="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        }
    )


@app.route("/")
def index():
    """Serve the main page."""
    return render_template("index.html")


@app.route("/api/status")
def api_status():
    """Check if the API is available for comic generation (no external calls)."""
    if get_openai_api_key() is None:
        return jsonify({"api_available": False, "reason": "missing_api_key"})
    return jsonify({"api_available": True})


def generation_unavailable():
    """Return an error response if comic generation can't run, else None."""
    if get_openai_api_key() is None:
        return jsonify({"error": "OPENAI_API_KEY is not configured on the server"}), 503
    return None


@app.route("/api/comics")
def list_comics():
    """List available comics."""
    registry = ComicRegistry(comics_dir=COMICS_DIR)
    comics = registry.get_available_comics()
    return jsonify([
        {
            "id": c.id,
            "name": c.name,
            "name_no": c.name_no,
            "description": c.description,
            "description_no": c.description_no,
            "style": c.style,
            "panel_font": c.panel_font,
        }
        for c in comics
    ])


@app.route("/api/finish", methods=["POST"])
def finish_comic():
    """Finish and generate the comic strip."""
    data = json_body()
    session_id = data.get("session_id")

    if not session_id:
        return jsonify({"error": "Missing session_id"}), 400
    if not is_valid_session_id(session_id):
        return jsonify({"error": "Invalid session_id"}), 400

    session = get_session(session_id)
    if not session:
        return jsonify({"error": "Session not found"}), 404

    # If the user typed text in the last interactive panel before clicking
    # Finish, it is included in the strip.
    final_input = data.get("user_input")
    final_input = final_input.strip() if isinstance(final_input, str) else ""

    try:
        result = session.finish(final_input)
        sessions.pop(session_id, None)
        session_timestamps.pop(session_id, None)
        return jsonify(result)
    except Exception as e:
        print(f"Error finishing comic: {e}")
        return jsonify({"error": "Failed to generate comic strip"}), 500


@app.route("/api/start-stream", methods=["POST"])
def start_comic_stream():
    """Start a new comic session with streaming image generation."""
    unavailable = generation_unavailable()
    if unavailable:
        return unavailable

    data = json_body()
    comic_id = data.get("comic_id")
    session_id = data.get("session_id")
    language = data.get("language", "no")

    if not comic_id or not session_id:
        return jsonify({"error": "Missing comic_id or session_id"}), 400
    if not is_valid_session_id(session_id) or not isinstance(comic_id, str):
        return jsonify({"error": "Invalid session_id or comic_id"}), 400
    if ComicRegistry(comics_dir=COMICS_DIR).get_comic_config_dir(comic_id) is None:
        return jsonify({"error": "Comic not found"}), 404

    cleanup_stale_sessions()

    try:
        session = ComicSession(comic_id, language=language)
        sessions[session_id] = session
        touch_session(session_id)
        return event_stream(session.start_streaming())
    except Exception as e:
        print(f"Error starting comic: {e}")
        return jsonify({"error": "Failed to start comic session"}), 500


@app.route("/api/submit-stream", methods=["POST"])
def submit_panel_stream():
    """Submit user's input and stream the next panel generation."""
    unavailable = generation_unavailable()
    if unavailable:
        return unavailable

    data = json_body()
    session_id = data.get("session_id")
    user_input_text = data.get("user_input") or ""
    language = data.get("language", "no")

    if not session_id:
        return jsonify({"error": "Missing session_id"}), 400
    if not is_valid_session_id(session_id):
        return jsonify({"error": "Invalid session_id"}), 400
    if not isinstance(user_input_text, str):
        return jsonify({"error": "user_input must be a string"}), 400

    session = get_session(session_id)
    if not session:
        return jsonify({"error": "Session not found"}), 404

    # Update language in case user switched mid-session
    session.language = language
    session.narratron.language = language

    return event_stream(session.submit_panel_streaming(user_input_text))
